import { createStore } from 'redux';

// Define the initial state
const initialState = {
  question: {
    text: '',
    answer: '',
    priority: 1
  }
};

// Define the reducer function
const questionReducer = (state = initialState, action) => {
  switch (action.type) {
    case 'UPDATE_QUESTION':
      return {
        ...state,
        question: {
          ...state.question,
          [action.payload.field]: action.payload.value
        }
      };
    default:
