### JWT (JSON Web Token) Authentication

For JWT authentication, you need to generate a JWT on successful authentication and validate the JWT for subsequent requests.

1. **Add JWT Dependencies:**

   ```xml
   <dependency>
       <groupId>io.jsonwebtoken</groupId>
       <artifactId>jjwt</artifactId>
       <version>0.9.1</version>
   </dependency>
   ```

2. **Create a JWT Utility Class:**

   ```java
   import io.jsonwebtoken.Claims;
   import io.jsonwebtoken.Jwts;
   import io.jsonwebtoken.SignatureAlgorithm;
   import org.springframework.stereotype.Component;

   import java.util.Date;

   @Component
   public class JwtUtil {

       private String secret = "your_secret_key";

       public String generateToken(String username) {
           return Jwts.builder()
               .setSubject(username)
               .setIssuedAt(new Date())
               .setExpiration(new Date(System.currentTimeMillis() + 1000 * 60 * 60 * 10))
               .signWith(SignatureAlgorithm.HS256, secret)
               .compact();
       }

       public Claims extractClaims(String token) {
           return Jwts.parser()
               .setSigningKey(secret)
               .parseClaimsJws(token)
               .getBody();
       }

       public boolean validateToken(String token, String username) {
           return extractClaims(token).getSubject().equals(username) && !isTokenExpired(token);
       }

       private boolean isTokenExpired(String token) {
           return extractClaims(token).getExpiration().before(new Date());
       }
   }
   ```

3. **Configure JWT in Security Config:**

   ```java
   import org.springframework.beans.factory.annotation.Autowired;
   import org.springframework.context.annotation.Bean;
   import org.springframework.context.annotation.Configuration;
   import org.springframework.security.authentication.AuthenticationManager;
   import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;
   import org.springframework.security.config.annotation.web.builders.HttpSecurity;
   import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
   import org.springframework.security.config.http.SessionCreationPolicy;
   import org.springframework.security.web.SecurityFilterChain;
   import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;

   @Configuration
   @EnableWebSecurity
   public class SecurityConfig {

       @Autowired
       private JwtRequestFilter jwtRequestFilter;

       @Bean
       public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
           http
               .csrf().disable()
               .authorizeRequests()
                   .antMatchers("/authenticate").permitAll()
                   .anyRequest().authenticated()
                   .and()
               .sessionManagement().sessionCreationPolicy(SessionCreationPolicy.STATELESS);
           http.addFilterBefore(jwtRequestFilter, UsernamePasswordAuthenticationFilter.class);
           return http.build();
       }

       @Bean
       public AuthenticationManager authenticationManager(AuthenticationConfiguration authenticationConfiguration) throws Exception {
           return authenticationConfiguration.getAuthenticationManager();
       }
   }
   ```

