    private static List<LineInfoPojo> getLevelNameUniqueIdAndChildrenMap(List<LineInfoPojo> maps, int step) {
        log("""
            1. Find firstNonZeroIndentation, if after traversal, firstNonZeroIndentation is still 0, then return map
