import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

public class ListOfObjectsToListOfMaps {

    public static void main(String[] args) {
        List<Student> students = List.of(
            new Student(1, "John", 20),
            new Student(2, "Alice", 22),
            new Student(3, "Bob", 21)
        );

        List<Map<String, Object>> studentMaps = students.stream()
            .map(student -> {
                Map<String, Object> studentMap = Map.of(
                    "id", student.getId(),
                    "name", student.getName(),
                    "age", student.getAge()
                );
                return studentMap;
            })
            .collect(Collectors.toList());

        // Print the list of maps
        studentMaps.forEach(System.out::println);
    }
}
```

