import React, { useState } from 'react';
import TagList from './TagList';
import GoldRateCalculator from './GoldRateCalculator';
import ComparisonContainer from './ComparisonContainer';
import ComparisonTableContainer from './ComparisonTableContainer';
import StudentList from './StudentList';

const tabButtonStyle = {
  padding: '10px 20px',
  border: '1px solid #007bff',
  cursor: 'pointer',
};

const TabNames = {
  listUsers: 'listUsers',
  goldRateCalculator: 'goldRateCalculator',
  comparisonContainer: 'comparisonContainer',
  comparisonTableContainer: 'comparisonTableContainer',
  studentListContainer: 'studentListContainer',
};

const tabsData = [
  { name: 'Tags', tab: TabNames.listUsers, component: TagList },
  { name: 'GoldRate Calculator', tab: TabNames.goldRateCalculator, component: GoldRateCalculator },
  { name: 'Comparison Container', tab: TabNames.comparisonContainer, component: ComparisonContainer },
  { name: 'Comparison Table Container', tab: TabNames.comparisonTableContainer, component: ComparisonTableContainer },
  { name: 'Student List Container', tab: TabNames.studentListContainer, component: StudentList, props: { students: [] } },
];

const SettingDashboard = ({ students }) => {
  const [activeTab, setActiveTab] = useState(TabNames.listUsers);

  const handleTabChange = (tab) => {
    setActiveTab(tab);
  };

  const ActiveComponent = tabsData.find(tab => tab.tab === activeTab)?.component || null;

  return (
    <div>
      <h2>Setting Dashboard</h2>
      <div style={{ display: 'flex', gap: '10px' }}>
        {tabsData.map(({ name, tab }) => (
          <button
            key={tab}
            style={{
              ...tabButtonStyle,
              background: activeTab === tab ? '#007bff' : 'white',
              color: activeTab === tab ? 'white' : 'black',
            }}
            onClick={() => handleTabChange(tab)}
          >
            {name}
          </button>
        ))}
      </div>
      <div style={{ marginTop: '10px' }}>
        {ActiveComponent && <ActiveComponent {...(activeTab === TabNames.studentListContainer ? { students } : {})} />}
      </div>
    </div>
  );
};

export default SettingDashboard;
```

### Notes
1. Ensure the components (`TagList`, `GoldRateCalculator`, `ComparisonContainer`, `ComparisonTableContainer`, `StudentList`) are imported correctly.
2. The `students` prop is passed specifically to the `StudentList` component when its tab is active. Adjust the component and props as needed.

