import React, { Component } from 'react';

class CronExpressionGenerator extends Component {
  constructor(props) {
    super(props);
    this.state = {
      minute: '*',
      hour: '*',
      dayOfMonth: '*',
      month: '*',
      dayOfWeek: '*',
      cronExpression: '* * * * *', // Default expression
    };
  }

