            <label>Day of Month:</label>
            <input
              type="text"
              name="dayOfMonth"
              value={this.state.dayOfMonth}
              onChange={this.handleInputChange}
            />
          </div>
          <div>
            <label>Month:</label>
            <input
              type="text"
              name="month"
              value={this.state.month}
              onChange={this.handleInputChange}
            />
          </div>
          <div>
            <label>Day of Week:</label>
            <input
              type="text"
              name="dayOfWeek"
              value={this.state.dayOfWeek}
              onChange={this.handleInputChange}
            />
          </div>
        </form>
        <div>
          <h2>Generated Cron Expression:</h2>
