const express = require('express');
const bodyParser = require('body-parser');
const mongoose = require('mongoose');

const app = express();

// MongoDB setup
const mongoURL = 'mongodb://localhost:27017'; // Replace with your MongoDB connection URL
const dbName = 'your-database-name'; // Replace with your database name
mongoose.connect(`${mongoURL}/${dbName}`, {
  useNewUrlParser: true,
  useUnifiedTopology: true,
});

// Create a Mongoose model for the "Activity" document
const Activity = mongoose.model('Activity', {
  title: String,
  description: String,
  date: String,
  createdDate: Date,
  shouldContinue: Boolean,
});

// Middleware to parse JSON requests
app.use(bodyParser.json());

// RESTful endpoints

// Create an activity
app.post('/activities', async (req, res) => {
  try {
    const activity = new Activity(req.body);
    await activity.save();
    res.status(201).json(activity);
  } catch (error) {
    res.status(400).json({ error: 'Unable to create the activity.' });
  }
});

// Get all activities
app.get('/activities', async (req, res) => {
  try {
    const activities = await Activity.find();
    res.json(activities);
  } catch (error) {
    res.status(500).json({ error: 'Unable to fetch activities.' });
  }
});

// Get a single activity by ID
app.get('/activities/:id', async (req, res) => {
  try {
    const activity = await Activity.findById(req.params.id);
    if (!activity) {
      return res.status(404).json({ error: 'Activity not found.' });
    }
    res.json(activity);
  } catch (error) {
    res.status(500).json({ error: 'Unable to fetch the activity.' });
  }
});

// Update an activity by ID
app.put('/activities/:id', async (req, res) => {
  try {
    const activity = await Activity.findByIdAndUpdate(req.params.id, req.body, {
      new: true,
    });
    if (!activity) {
      return res.status(404).json({ error: 'Activity not found.' });
    }
    res.json(activity);
  } catch (error) {
    res.status(500).json({ error: 'Unable to update the activity.' });
  }
});

// Delete an activity by ID
app.delete('/activities/:id', async (req, res) => {
  try {
    const activity = await Activity.findByIdAndDelete(req.params.id);
    if (!activity) {
      return res.status(404).json({ error: 'Activity not found.' });
    }
