        if (!parentTopic) {
            throw new Error('Parent topic not found');
        }

        // Fetch child topic
        const childTopic = await topicsCollection.findOne({ _id: new ObjectId(childId) });
        if (!childTopic) {
            throw new Error('Child topic not found');
        }

        // Check if child already exists in parent's children array
        if (parentTopic.children && parentTopic.children.includes(childId)) {
            throw new Error('Child topic already added');
        }

        // Check if parent or any ancestor is being added as a child
        if (await isAncestor(db, childId, parentId)) {
            throw new Error('Cannot add a parent or ancestor as a child');
        }

        // Add child to parent's children array
        await topicsCollection.updateOne(
            { _id: new ObjectId(parentId) },
            { $addToSet: { children: new ObjectId(childId) } }
